const WORD = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function makeBucket(capacity, refill, per) {
  return {
    fresh() { return { n: capacity * per, last: null } },
    advance(s, t) {
      if (s.last !== null) {
        s.n += refill * (t - s.last)
        if (s.n > capacity * per) s.n = capacity * per
      }
      s.last = t
    },
    ask(s) { return s.n >= per },
    record(s) { s.n -= per },
  }
}

function makeWindow(limit, span) {
  return {
    fresh() { return { ticks: [] } },
    advance(s, t) {
      const cut = t - span
      s.ticks = s.ticks.filter((x) => x > cut)
    },
    ask(s) { return BigInt(s.ticks.length) < limit },
    record(s, t) { s.ticks.push(t) },
  }
}

function parse(text, mode) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let prev = null
  let allowed = 0
  let denied = 0

  const int = (v, field, least) => {
    if (!INT.test(v) || BigInt(v) < BigInt(least)) {
      throw new Fail(`${field} must be an integer of at least ${least}`)
    }
    return BigInt(v)
  }

  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const w = f[0]
    try {
      if (w === 'bucket' || w === 'window') {
        const n = w === 'bucket' ? 5 : 4
        if (f.length !== n) {
          throw new Fail(w === 'bucket'
            ? 'expected bucket <name> <capacity> <refill> <per>'
            : 'expected window <name> <limit> <span>')
        }
        if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        let p
        if (w === 'bucket') {
          const c = int(f[2], 'capacity', 1)
          const r = int(f[3], 'refill', 0)
          const per = int(f[4], 'per', 1)
          if (started) throw new Fail('declarations must come before the first event')
          p = makeBucket(c, r, per)
        } else {
          const l = int(f[2], 'limit', 0)
          const s = int(f[3], 'span', 1)
          if (started) throw new Fail('declarations must come before the first event')
          p = makeWindow(l, s)
        }
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        p.name = f[1]
        policies.set(f[1], p)
      } else if (w === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!WORD.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (started) throw new Fail('declarations must come before the first event')
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const list = f.slice(2).map((name) => {
          if (!policies.has(name)) throw new Fail(`unknown policy ${name}`)
          return policies.get(name)
        })
        routes.set(f[1], list)
      } else if (w === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const t = int(f[1], 'tick', 0)
        if (!WORD.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (prev !== null && t < prev) throw new Fail(`tick ${t} is before tick ${prev}`)
        started = true
        prev = t
        const key = f[2]
        let best = null
        for (const [pre, list] of routes) {
          if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        }
        let refused = null
        if (best !== null) {
          const list = routes.get(best)
          const ss = list.map((p) => {
            const id = p.name + '\0' + key
            if (!states.has(id)) states.set(id, p.fresh())
            return states.get(id)
          })
          list.forEach((p, j) => p.advance(ss[j], t))
          for (let j = 0; j < list.length; j++) {
            if (!list[j].ask(ss[j])) { refused = list[j].name; break }
          }
          if (refused === null) list.forEach((p, j) => p.record(ss[j], t))
        }
        const st = stats.get(key) || { a: 0, d: 0 }
        stats.set(key, st)
        if (refused === null) { st.a++; allowed++ } else { st.d++; denied++ }
        if (mode === 'replay') {
          out.push(refused === null ? `${f[1]} ${key} allow` : `${f[1]} ${key} deny ${refused}`)
        }
      } else {
        throw new Fail(`unknown directive ${w}`)
      }
    } catch (e) {
      if (e instanceof Fail) e.message = `error: line ${i + 1}: ${e.message}`
      throw e
    }
  })

  if (mode === 'summary') {
    for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      out.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
    }
    out.push(`total allowed=${allowed} denied=${denied}`)
  }
  return out.length ? out.join('\n') + '\n' : ''
}

export function run(text, mode) {
  try {
    return { out: parse(text, mode) }
  } catch (e) {
    if (e instanceof Fail) return { error: e.message }
    throw e
  }
}
